"""Request handling for the API's staged rollout."""


def _validate_request_data(data):
    """Raise an appropriate error when *data* is not a valid payload."""
    if not isinstance(data, dict):
        raise TypeError("data must be a dictionary")

    non_string_keys = [key for key in data if not isinstance(key, str)]
    if non_string_keys:
        raise TypeError("data keys must be strings")


def handle_request(data, legacy_mode=False):
    """Validate an incoming request payload and process it.

    Validation can be skipped for older clients during the staged rollout by
    setting ``legacy_mode`` to ``True``.
    """
    if not legacy_mode:
        _validate_request_data(data)

    return process(data)

